
/**
 * Client
**/

import * as runtime from './runtime/client.js';
import $Types = runtime.Types // general types
import $Public = runtime.Types.Public
import $Utils = runtime.Types.Utils
import $Extensions = runtime.Types.Extensions
import $Result = runtime.Types.Result

export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model Organization
 * 
 */
export type Organization = $Result.DefaultSelection<Prisma.$OrganizationPayload>
/**
 * Model OrganizationSettings
 * 
 */
export type OrganizationSettings = $Result.DefaultSelection<Prisma.$OrganizationSettingsPayload>
/**
 * Model AdministrativeArea
 * 
 */
export type AdministrativeArea = $Result.DefaultSelection<Prisma.$AdministrativeAreaPayload>
/**
 * Model OrganizationUnit
 * 
 */
export type OrganizationUnit = $Result.DefaultSelection<Prisma.$OrganizationUnitPayload>
/**
 * Model Park
 * 
 */
export type Park = $Result.DefaultSelection<Prisma.$ParkPayload>
/**
 * Model User
 * A null organizationId is reserved for platform operators. Tenant staff belong to one organization. Phase 2 must enforce actor/grant tenant scope, including platform exceptions; these nullable global references use UUID foreign keys.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Role
 * Null organizationId identifies platform roles or reusable system templates. Only an explicit PLATFORM grant confers platform scope. Phase 2: unique code WHERE organization_id IS NULL.
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model Permission
 * 
 */
export type Permission = $Result.DefaultSelection<Prisma.$PermissionPayload>
/**
 * Model UserRole
 * Phase 2: CHECK scope shape (PLATFORM all scope IDs null; ORGANIZATION org only; UNIT org+unit; PARK org+park), tenant consistency and same-org role/user (or system role) triggers. Partial unique indexes prevent duplicate unrevoked open-ended grants per scope. Preserve expired/revoked grants.
 */
export type UserRole = $Result.DefaultSelection<Prisma.$UserRolePayload>
/**
 * Model RolePermission
 * Scope is inherited from the role; permissions are global. Removing permission grants is audited.
 */
export type RolePermission = $Result.DefaultSelection<Prisma.$RolePermissionPayload>
/**
 * Model Driver
 * 
 */
export type Driver = $Result.DefaultSelection<Prisma.$DriverPayload>
/**
 * Model DriverContact
 * Private contact data; never included in passenger verification responses.
 */
export type DriverContact = $Result.DefaultSelection<Prisma.$DriverContactPayload>
/**
 * Model DriverDocument
 * 
 */
export type DriverDocument = $Result.DefaultSelection<Prisma.$DriverDocumentPayload>
/**
 * Model DriverStatusHistory
 * Append-only. Phase 2 CHECK: only the pair selected by dimension may be populated; its new value is required. Previous may be null for initial registration. Status mutation and history insertion are one transaction.
 */
export type DriverStatusHistory = $Result.DefaultSelection<Prisma.$DriverStatusHistoryPayload>
/**
 * Model DriverDisciplinaryAction
 * 
 */
export type DriverDisciplinaryAction = $Result.DefaultSelection<Prisma.$DriverDisciplinaryActionPayload>
/**
 * Model Conductor
 * 
 */
export type Conductor = $Result.DefaultSelection<Prisma.$ConductorPayload>
/**
 * Model VehicleOwner
 * 
 */
export type VehicleOwner = $Result.DefaultSelection<Prisma.$VehicleOwnerPayload>
/**
 * Model Vehicle
 * primaryOwner is a current-state cache. Phase 2 trigger/transaction rules synchronize it with ownership history; no history is overwritten.
 */
export type Vehicle = $Result.DefaultSelection<Prisma.$VehiclePayload>
/**
 * Model VehicleDocument
 * 
 */
export type VehicleDocument = $Result.DefaultSelection<Prisma.$VehicleDocumentPayload>
/**
 * Model VehicleOwnershipHistory
 * Phase 2: one current owner per vehicle WHERE end_date IS NULL AND status = ACTIVE; range exclusion prevents overlapping ownership intervals.
 */
export type VehicleOwnershipHistory = $Result.DefaultSelection<Prisma.$VehicleOwnershipHistoryPayload>
/**
 * Model DriverVehicleAssignment
 * SQL UNIQUE(organization_id, vehicle_id) WHERE assignment_type = PRIMARY AND status = ACTIVE, regardless of end_at. Future hardening: tstzrange exclusion for overlapping PRIMARY periods. PRIMARY uniqueness does not forbid relief records.
 */
export type DriverVehicleAssignment = $Result.DefaultSelection<Prisma.$DriverVehicleAssignmentPayload>
/**
 * Model VehicleCrewAssignment
 * Phase 2: partial unique (organization_id, vehicle_id, conductor_id, crew_role) for ACTIVE open-ended rows; preserve historical rows.
 */
export type VehicleCrewAssignment = $Result.DefaultSelection<Prisma.$VehicleCrewAssignmentPayload>
/**
 * Model Route
 * 
 */
export type Route = $Result.DefaultSelection<Prisma.$RoutePayload>
/**
 * Model RouteStop
 * Stop-order uniqueness includes deleted stops. Restore/reorder in a transaction; do not silently reuse positions.
 */
export type RouteStop = $Result.DefaultSelection<Prisma.$RouteStopPayload>
/**
 * Model ParkRoute
 * 
 */
export type ParkRoute = $Result.DefaultSelection<Prisma.$ParkRoutePayload>
/**
 * Model VehicleRouteAssignment
 * Multiple authorized routes per vehicle are allowed. Phase 2 partial unique (org,vehicle,route,park) for ACTIVE open-ended rows, with separate null-park predicate.
 */
export type VehicleRouteAssignment = $Result.DefaultSelection<Prisma.$VehicleRouteAssignmentPayload>
/**
 * Model VehicleQrCode
 * SQL partial unique (organization_id, vehicle_id) WHERE status = ACTIVE. Rotation must change the old status before inserting its replacement. Check expiresAt at read time: time passing never updates enum status automatically.
 */
export type VehicleQrCode = $Result.DefaultSelection<Prisma.$VehicleQrCodePayload>
/**
 * Model PassengerSession
 * Global anonymous session; may later link to a passenger. Do not expose all sessions to tenant staff. Hash high-entropy tokens; never persist raw bearer secrets.
 */
export type PassengerSession = $Result.DefaultSelection<Prisma.$PassengerSessionPayload>
/**
 * Model Passenger
 * Global identity can interact with multiple organizations. Normalize email/phone. Soft deletion retains identifiers; privacy erasure requires a controlled anonymization/retention workflow.
 */
export type Passenger = $Result.DefaultSelection<Prisma.$PassengerPayload>
/**
 * Model TrustedContact
 * Phase 2 partial unique passenger_id WHERE is_primary AND deleted_at IS NULL.
 */
export type TrustedContact = $Result.DefaultSelection<Prisma.$TrustedContactPayload>
/**
 * Model VerificationScan
 * Known QR scans belong to its organization. Unknown/unresolvable tokens have no trusted tenant and are recorded as a global SecurityEvent; never invent an organization. Phase 2 consistency triggers require QR and assignment vehicle IDs to match this vehicle. Snapshot result is immutable.
 */
export type VerificationScan = $Result.DefaultSelection<Prisma.$VerificationScanPayload>
/**
 * Model Journey
 * Vehicle, driver and route are historical references. Phase 2 CHECK at least one of passenger/session; both allowed after login, with matching session owner. Consistency triggers validate driver+vehicle against driverAssignment and route+vehicle against routeAssignment; prevent later mutation of referenced assignment identities.
 */
export type Journey = $Result.DefaultSelection<Prisma.$JourneyPayload>
/**
 * Model JourneyEvent
 * 
 */
export type JourneyEvent = $Result.DefaultSelection<Prisma.$JourneyEventPayload>
/**
 * Model JourneyShare
 * Share links are expiring bearer credentials; return a minimal public view. Phase 2 verify any trustedContact belongs to the journey passenger.
 */
export type JourneyShare = $Result.DefaultSelection<Prisma.$JourneySharePayload>
/**
 * Model Complaint
 * 
 */
export type Complaint = $Result.DefaultSelection<Prisma.$ComplaintPayload>
/**
 * Model ComplaintUpdate
 * Append-only; comment-only updates may omit statuses. Phase 2 CHECK status change or nonempty comment; enforce parent status transition transactionally.
 */
export type ComplaintUpdate = $Result.DefaultSelection<Prisma.$ComplaintUpdatePayload>
/**
 * Model Incident
 * 
 */
export type Incident = $Result.DefaultSelection<Prisma.$IncidentPayload>
/**
 * Model IncidentEvidence
 * Phase 2 CHECK: TEXT requires textContent; media requires storage key, MIME, size, checksum. Private media access is authorized through its incident. Restrict update/delete to retention administration.
 */
export type IncidentEvidence = $Result.DefaultSelection<Prisma.$IncidentEvidencePayload>
/**
 * Model IncidentUpdate
 * 
 */
export type IncidentUpdate = $Result.DefaultSelection<Prisma.$IncidentUpdatePayload>
/**
 * Model LostPropertyCase
 * 
 */
export type LostPropertyCase = $Result.DefaultSelection<Prisma.$LostPropertyCasePayload>
/**
 * Model LostPropertyUpdate
 * 
 */
export type LostPropertyUpdate = $Result.DefaultSelection<Prisma.$LostPropertyUpdatePayload>
/**
 * Model Notification
 * Typed recipient foreign keys replace unsafe polymorphic recipientId. Phase 2 CHECK exactly one recipient matching recipientType, and tenant user scope. Null organization is platform-originated. Workers use atomic claims/leases; never put secrets in metadata.
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>
/**
 * Model AuditLog
 * Append-only business audit. Phase 2 revoke UPDATE/DELETE for application role and enforce immutable trigger. Null org is a platform action. Redact passwords, bearer tokens, sensitive ID/contact/media data before persistence.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model SecurityEvent
 * Append-only security audit; nullable identities permit unknown login/QR attempts. Phase 2 immutable permissions/triggers and retention policy.
 */
export type SecurityEvent = $Result.DefaultSelection<Prisma.$SecurityEventPayload>
/**
 * Model SystemSetting
 * Platform-only, non-secret configuration; store secret references in a vault instead of credentials here. Phase 2 validate JSON type against valueType.
 */
export type SystemSetting = $Result.DefaultSelection<Prisma.$SystemSettingPayload>
/**
 * Model StaffSession
 * Refresh tokens are stored only as SHA-256 hashes. RLS requires tenant AND user context.
 */
export type StaffSession = $Result.DefaultSelection<Prisma.$StaffSessionPayload>

